use std::path::PathBuf;
use ts_rs::TS;
fn main() -> anyhow::Result<()> {
    let directory = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../../packages/shared/src/generated/rust");
    std::fs::create_dir_all(&directory)?;
    let declaration = format!(
        "// Generated by cargo run -p astra-api --bin export-types. Do not edit.\nexport {}\n",
        astra_api::user::UserDto::decl(&ts_rs::Config::default())
    );
    std::fs::write(directory.join("UserDto.ts"), declaration)?;
    let config = ts_rs::Config::default();
    let wallet = format!(
        "// Generated by cargo run -p astra-api --bin export-types. Do not edit.\nexport {}\nexport {}\nexport {}\n",
        astra_api::wallet::WalletChain::decl(&config),
        astra_api::wallet::WalletAssetDto::decl(&config),
        astra_api::wallet::WalletDto::decl(&config)
    );
    std::fs::write(directory.join("WalletDto.ts"), wallet)?;
    let icon = format!(
        "// Generated by cargo run -p astra-api --bin export-types. Do not edit.\nexport {}\n",
        astra_api::asset_icon::IconResponse::decl(&ts_rs::Config::default())
    );
    std::fs::write(directory.join("IconResponse.ts"), icon)?;
    let market = format!(
        "// Generated by cargo run -p astra-api --bin export-types. Do not edit.\nexport {}\nexport {}\n",
        astra_api::market::MarketCoinDto::decl(&ts_rs::Config::default()),
        astra_api::market::MarketPageDto::decl(&ts_rs::Config::default())
    );
    std::fs::write(directory.join("MarketDto.ts"), market)?;
    let news = format!(
        "// Generated by cargo run -p astra-api --bin export-types. Do not edit.\nexport {}\nexport {}\n",
        astra_api::news::NewsArticleDto::decl(&ts_rs::Config::default()),
        astra_api::news::NewsPageDto::decl(&ts_rs::Config::default())
    );
    std::fs::write(directory.join("NewsDto.ts"), news)?;
    Ok(())
}
